import { chromium } from '@playwright/test'
const b=await chromium.launch({executablePath:'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'})
for (const kind of ['pre','mid','post']) {
  const pg=await b.newPage({viewport:{width:390,height:844}})
  await pg.goto('http://127.0.0.1:8099/#/pages/inspection/index?kind='+kind,{waitUntil:'domcontentloaded',timeout:25000}).catch(()=>{})
  await pg.waitForTimeout(2200)
  const info=await pg.evaluate(()=>{
    const heads=[...document.querySelectorAll('.upload-head')].map(h=>{
      const label=h.querySelector('.card-h3')?.textContent.trim()
      const count=h.querySelector('.label-small')?.textContent.trim()
      const hr=h.getBoundingClientRect(), cr=h.querySelector('.label-small')?.getBoundingClientRect()
      return {label, count, countAtRight: cr? Math.round(hr.right-cr.right):null}
    })
    const hints=[...document.querySelectorAll('.card .hint')].map(h=>h.textContent.trim())
    const remarkLabels=[...document.querySelectorAll('.field-block-label')].map(e=>e.textContent.trim()).filter(t=>t==='备注')
    return {heads, hintCount:hints.length, hints, remarkLabelCount:remarkLabels.length}
  })
  console.log(kind, JSON.stringify(info))
  await pg.close()
}
await b.close()

